<div class="col-lg-4"><aside class="card summary bg-white"><div class="card-body p-4"><span class="badge rounded-pill bg-success-subtle text-success mb-3">Cara pengisian</span><h2 class="h6 fw-bold mb-3">Data yang perlu disiapkan</h2><ul><li><i class="bi bi-person-check"></i><span>Identitas dasar penanam dan instansi</span></li><li><i class="bi bi-tree"></i><span>Jenis serta jumlah pohon yang ditanam</span></li><li><i class="bi bi-geo-alt"></i><span>Titik lokasi dari GPS atau peta</span></li><li><i class="bi bi-camera"></i><span>Foto dokumentasi tanaman</span></li></ul><div class="map-help mt-3"><i class="bi bi-shield-lock me-1"></i>Token akses hanya memberi izin untuk mencatat data, bukan melihat data peserta lain.</div></div></aside></div></div></main>
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>document.addEventListener('DOMContentLoaded',()=>{const map=L.map('planting-map').setView([-8.4095,115.1889],9);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors'}).addTo(map);let marker;const lat=document.getElementById('latitude'),lng=document.getElementById('longitude'),status=document.getElementById('location-status');const setLocation=(point)=>{lat.value=point.lat.toFixed(7);lng.value=point.lng.toFixed(7);if(marker){marker.setLatLng(point)}else{marker=L.marker(point).addTo(map)}status.textContent='Lokasi berhasil dipilih';status.className='form-text ms-2 text-success'};map.on('click',e=>setLocation(e.latlng));document.getElementById('locate').addEventListener('click',()=>{if(!navigator.geolocation){status.textContent='GPS tidak tersedia di perangkat ini';return}status.textContent='Mencari lokasi...';navigator.geolocation.getCurrentPosition(position=>{const point={lat:position.coords.latitude,lng:position.coords.longitude};map.setView(point,15);setLocation(point)},()=>{status.textContent='Lokasi tidak dapat diakses. Periksa izin GPS.'})});document.getElementById('photo').addEventListener('change',event=>{const file=event.target.files[0],preview=document.getElementById('photo-preview');if(file){preview.src=URL.createObjectURL(file);preview.classList.remove('d-none')}})});</script>
