    $defaultPlantingLocation = ['location_name' => $accessToken->location_name, 'latitude' => $accessToken->latitude, 'longitude' => $accessToken->longitude];
    $plantTypeOptions = $plantTypes->isNotEmpty() ? $plantTypes->values()->all() : ['Mahoni', 'Trembesi', 'Mangrove', 'Beringin', 'Bambu', 'Nyamplung'];
    $agencyOptions = $agencies->map(fn ($agency) => ['name' => $agency->short_name ?: $agency->name])->values()->all();
@endphp
<script>
document.addEventListener('DOMContentLoaded',()=>{
    const defaults=@json($defaultPlantingLocation);
    const oldLocation=@json(old('location_name')); const oldLatitude=@json(old('latitude')); const oldLongitude=@json(old('longitude'));
    document.getElementById('location_name').value=oldLocation||defaults.location_name||'';
    document.getElementById('latitude').value=oldLatitude||defaults.latitude||'';
    document.getElementById('longitude').value=oldLongitude||defaults.longitude||'';
    const types=@json($plantTypeOptions);
    const typeSelect=document.getElementById('plant_type'); const selected=@json(old('plant_type')); typeSelect.innerHTML='<option value="">Pilih jenis tanaman</option>'+types.map(type=>`<option value="${type}" ${type===selected?'selected':''}>${type}</option>`).join('');
    const agencies=@json($agencyOptions); const organization=document.getElementById('organization'); const selectedAgency=@json(old('organization')); const select=document.createElement('select'); select.id='organization'; select.name='organization'; select.className=organization.className; select.innerHTML='<option value="">Pilih instansi / komunitas</option>'+agencies.map(agency=>`<option value="${agency.name}" ${agency.name===selectedAgency?'selected':''}>${agency.name}</option>`).join(''); organization.replaceWith(select);
});
</script>
